package com.networkmonitorpro.data.repository; import android.content.*; import com.networkmonitorpro.data.db.AppDatabase; import com.networkmonitorpro.data.entity.Setting; public class SettingsRepository{ private final AppDatabase db; public SettingsRepository(Context c){db=AppDatabase.get(c);} public void put(String k,String v){AppExecutors.IO.execute(()->db.settingDao().put(new Setting(k,v)));} public String get(String k,String def){String v=db.settingDao().get(k); return v==null?def:v;} }
